// Validates that env vars match expected formats.
// Reports pass/fail only — never prints values.

const fs = require('fs');
const path = require('path');

const RULES = {
  DATABASE_URL:          /^postgres(ql)?:\/\/[^\s]+$/,
  AWS_ACCESS_KEY_ID:     /^AKIA[0-9A-Z]{16}$/,
  AWS_SECRET_ACCESS_KEY: /^[A-Za-z0-9/+=]{40}$/,
  ANTHROPIC_API_KEY:     /^sk-ant-[A-Za-z0-9_-]+$/,
  STRIPE_SECRET_KEY:     /^sk_(live|test)_[A-Za-z0-9]+$/,
  LOGFIRE_TOKEN:         /^[A-Za-z0-9_-]+$/,
};

function parseEnv(filePath) {
  const out = {};
  for (const line of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
    if (m) out[m[1]] = m[2];
  }
  return out;
}

const envPath = process.argv[2] || '.env.test';
const env = parseEnv(path.resolve(envPath));

let failed = 0;
for (const [name, pattern] of Object.entries(RULES)) {
  const value = env[name];
  if (value === undefined) {
    console.log(`MISSING  ${name}`);
    failed++;
  } else if (!pattern.test(value)) {
    console.log(`BAD_FMT  ${name}`);
    failed++;
  } else {
    console.log(`OK       ${name}`);
  }
}

process.exit(failed ? 1 : 0);

// Compares .env file values against a vault export by hash.
// Neither file's values are ever printed.
//
// Usage: node scripts/compare-env-to-vault.js .env.test vault-export.env

const fs = require('fs');
const crypto = require('crypto');

function parseEnv(filePath) {
  const out = {};
  for (const line of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
    if (m) out[m[1]] = m[2];
  }
  return out;
}

function hash(value) {
  // Salted hash so the digest itself isn't useful for offline comparison
  // against known credential databases.
  const salt = process.env.COMPARE_SALT;
  if (!salt) {
    console.error('Set COMPARE_SALT to a random string before running.');
    process.exit(2);
  }
  return crypto.createHmac('sha256', salt).update(value).digest('hex').slice(0, 16);
}

const [, , envPath, vaultPath] = process.argv;
if (!envPath || !vaultPath) {
  console.error('Usage: node compare-env-to-vault.js <env-file> <vault-file>');
  process.exit(2);
}

const env = parseEnv(envPath);
const vault = parseEnv(vaultPath);

const names = new Set([...Object.keys(env), ...Object.keys(vault)]);
for (const name of names) {
  if (!(name in env))   { console.log(`ENV_MISSING   ${name}`); continue; }
  if (!(name in vault)) { console.log(`VAULT_MISSING ${name}`); continue; }
  console.log(hash(env[name]) === hash(vault[name]) ? `MATCH         ${name}`
                                                    : `DIFFER        ${name}`);
}

