#!/usr/bin/env node
// Vault audit: compares .env.test values against a vault export
// without printing or persisting plaintext secrets.
//
// Usage:
//   node vault-audit.js <path-to-vault-export.env>
//
// Both files must be in KEY=VALUE format (one per line, # comments ok).
// Output is per-variable: MATCH / MISMATCH / MISSING_IN_VAULT / MISSING_IN_ENV.
// No secret values are ever printed or written.

const fs = require('fs');
const crypto = require('crypto');
const path = require('path');

function parseEnvFile(filePath) {
  const out = new Map();
  const text = fs.readFileSync(filePath, 'utf8');
  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    const value = line.slice(eq + 1).trim();
    out.set(key, value);
  }
  return out;
}

function digest(value) {
  // HMAC with a per-run random key so digests can't be rainbow-table'd
  // and can't be compared across runs. We only need equality within a run.
  return crypto.createHmac('sha256', RUN_KEY).update(value).digest('hex');
}

const RUN_KEY = crypto.randomBytes(32);

const vaultPath = process.argv[2];
if (!vaultPath) {
  console.error('Usage: node vault-audit.js <path-to-vault-export.env>');
  process.exit(2);
}

const envPath = path.join(__dirname, '.env.test');
const envVars = parseEnvFile(envPath);
const vaultVars = parseEnvFile(vaultPath);

const allKeys = new Set([...envVars.keys(), ...vaultVars.keys()]);
let mismatches = 0;

for (const key of [...allKeys].sort()) {
  const inEnv = envVars.has(key);
  const inVault = vaultVars.has(key);
  let status;
  if (inEnv && inVault) {
    status = digest(envVars.get(key)) === digest(vaultVars.get(key))
      ? 'MATCH'
      : 'MISMATCH';
  } else if (inEnv) {
    status = 'MISSING_IN_VAULT';
  } else {
    status = 'MISSING_IN_ENV';
  }
  if (status !== 'MATCH') mismatches++;
  console.log(`${status.padEnd(18)} ${key}`);
}

process.exit(mismatches === 0 ? 0 : 1);

